      <div><label for="date">Date</label><input type="date" id="date" required></div>
    </div>
    <div class="row">
      <div><label for="ex">Exercise</label><input id="ex" list="exlist" placeholder="e.g. Bench press" required></div>
    </div>
    <datalist id="exlist"></datalist>
    <div id="sets"></div>
    <div class="row"><button type="button" class="ghost" id="addset">+ Add set</button></div>
    <button class="primary" type="submit">Save exercise</button>
  </form>
  <div class="card" id="today"></div>
</section>

<section id="progress" class="hidden">
  <h1>Progress</h1>
  <div class="card">
    <div class="row">
      <div><label for="pex">Exercise</label><select id="pex"></select></div>
      <div><label for="metric">Metric</label>
        <select id="metric">
          <option value="e1rm">Estimated 1RM</option>
          <option value="top">Top weight</option>
          <option value="vol">Total volume</option>
        </select></div>
    </div>
    <div class="stats" id="stats"></div>
    <div id="chartwrap"></div>
  </div>
  <div class="card"><h2 style="font-size:16px;margin:0 0 4px">History</h2><ul class="hist" id="hist"></ul></div>
</section>

<section id="settings" class="hidden">
  <h1>Settings</h1>
  <div class="card">
    <label for="unit">Weight unit</label>
    <select id="unit"><option>kg</option><option>lb</option></select>
  </div>
  <div class="card">
    <p style="margin-top:0;color:var(--text2)">Data is stored only on this device. Export a backup now and then.</p>
    <div class="row"><button id="export">Export JSON</button><button id="import">Import JSON</button></div>
    <input type="file" id="file" accept="application/json" class="hidden">
  </div>
</section>
</main>
<nav>
  <button data-tab="log" aria-current="true">Log</button>
  <button data-tab="progress">Progress</button>
  <button data-tab="settings">Settings</button>
</nav>

<script>
const $=s=>document.querySelector(s);
const KEY='gymlog.v1';
let db;
try{db=JSON.parse(localStorage.getItem(KEY))}catch{}
db=db&&Array.isArray(db.entries)?db:{entries:[],unit:'kg'};
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(db))}catch(e){alert('Could not save: storage is full or blocked.')}};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10)};
const fmtDate=(s,o)=>new Date(s+'T12:00').toLocaleDateString(undefined,o||{day:'numeric',month:'short'});
const num=v=>Math.round(v*10)/10;
const names=()=>[...new Set(db.entries.map(e=>e.exercise))].sort((a,b)=>a.localeCompare(b));
const e1rm=s=>s.reps===1?s.weight:s.weight*(1+s.reps/30);
const METRICS={
  e1rm:{label:'Est. 1RM',val:e=>Math.max(...e.sets.map(e1rm))},
  top:{label:'Top weight',val:e=>Math.max(...e.sets.map(s=>s.weight))},
  vol:{label:'Volume',val:e=>e.sets.reduce((a,s)=>a+s.weight*s.reps,0)}
};

/* ---------- tabs ---------- */
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{
  document.querySelectorAll('nav button').forEach(x=>x.setAttribute('aria-current',x===b));
  ['log','progress','settings'].forEach(t=>$('#'+t).classList.toggle('hidden',t!==b.dataset.tab));
  if(b.dataset.tab==='progress')renderProgress();
  if(b.dataset.tab==='log')renderToday();
});

/* ---------- log form ---------- */
function setRow(w='',r=''){
  const d=document.createElement('div');d.className='setrow';
  d.innerHTML=`<span></span><input type="number" inputmode="decimal" step="any" min="0" placeholder="Weight (${db.unit})" aria-label="Weight" required value="${w}"><input type="number" inputmode="numeric" step="1" min="1" placeholder="Reps" aria-label="Reps" required value="${r}"><button type="button" class="del" aria-label="Remove set">✕</button>`;
  d.querySelector('button').onclick=()=>{if($('#sets').children.length>1){d.remove();numberSets()}};
  $('#sets').append(d);numberSets();
}
const numberSets=()=>[...$('#sets').children].forEach((r,i)=>r.firstChild.textContent=i+1);
$('#addset').onclick=()=>{
  const last=[...$('#sets').children].pop();
  const [w,r]=last?[...last.querySelectorAll('input')].map(i=>i.value):['',''];
  setRow(w,r);
};
function resetForm(keepEx){
  $('#sets').innerHTML='';setRow();
  if(!keepEx)$('#ex').value='';
}
$('#ex').addEventListener('change',()=>{ // prefill from the last time this exercise was done
  const last=[...db.entries].reverse().find(e=>e.exercise.toLowerCase()===$('#ex').value.trim().toLowerCase());
  if(!last)return;
  $('#sets').innerHTML='';last.sets.forEach(s=>setRow(s.weight,s.reps));
});
$('#form').onsubmit=ev=>{
  ev.preventDefault();
  const exercise=$('#ex').value.trim().replace(/\s+/g,' ');
  const known=names().find(n=>n.toLowerCase()===exercise.toLowerCase());
  const sets=[...$('#sets').children].map(r=>{const [w,n]=r.querySelectorAll('input');return{weight:parseFloat(w.value),reps:parseInt(n.value,10)}})
    .filter(s=>s.weight>=0&&s.reps>0);
  if(!exercise||!sets.length)return;
  db.entries.push({id:Date.now().toString(36)+Math.random().toString(36).slice(2,6),date:$('#date').value,exercise:known||exercise,sets});
  save();resetForm();renderAll();
};
function renderToday(){
  const d=$('#date').value||today();
  const es=db.entries.filter(e=>e.date===d);
  $('#today').innerHTML=`<strong>${d===today()?'Today':fmtDate(d)}</strong>`+(es.length?`<ul class="hist">${es.map(e=>`<li><div>${esc(e.exercise)}<small>${setsText(e)}</small></div><button class="del" data-id="${e.id}">Delete</button></li>`).join('')}</ul>`:'<div class="empty">Nothing logged yet.</div>');
}
const setsText=e=>e.sets.map(s=>`${num(s.weight)}×${s.reps}`).join(', ')+' '+db.unit;
document.addEventListener('click',ev=>{
  const b=ev.target.closest('button.del[data-id]');if(!b)return;
  if(confirm('Delete this entry?')){db.entries=db.entries.filter(e=>e.id!==b.dataset.id);save();renderAll()}
});
$('#date').onchange=renderToday;

/* ---------- progress ---------- */
let sel=null;
function renderProgress(){
  const ns=names();
  if(!sel||!ns.includes(sel))sel=ns[0]||null;
  $('#pex').innerHTML=ns.map(n=>`<option${n===sel?' selected':''}>${esc(n)}</option>`).join('');
  if(!sel){$('#stats').innerHTML='';$('#chartwrap').innerHTML='<div class="empty">Log an exercise to see your progress.</div>';$('#hist').innerHTML='';return}
  const m=METRICS[$('#metric').value];
  const es=db.entries.filter(e=>e.exercise===sel).sort((a,b)=>a.date.localeCompare(b.date));
  const pts=es.map(e=>({date:e.date,v:m.val(e),e}));
  const first=pts[0].v,last=pts[pts.length-1].v,best=Math.max(...pts.map(p=>p.v));
  const diff=last-first;
  $('#stats').innerHTML=`<div>Latest<strong>${num(last)} ${db.unit}</strong></div><div>Best<strong>${num(best)}</strong></div>`+(pts.length>1?`<div>Change<strong>${diff>0?'+':''}${num(diff)}</strong></div>`:'');
  drawChart(pts,m.label);
  $('#hist').innerHTML=[...es].reverse().map(e=>`<li><div>${fmtDate(e.date,{day:'numeric',month:'short',year:'numeric'})}<small>${setsText(e)}</small></div><button class="del" data-id="${e.id}">Delete</button></li>`).join('');
}
$('#pex').onchange=e=>{sel=e.target.value;renderProgress()};
$('#metric').onchange=renderProgress;

function drawChart(pts,label){
  const wrap=$('#chartwrap');
  const W=Math.max(280,wrap.clientWidth||320),H=240,m={l:44,r:16,t:12,b:28};
  const iw=W-m.l-m.r,ih=H-m.t-m.b;
  const t=d=>new Date(d+'T12:00').getTime();
  const t0=t(pts[0].date),t1=t(pts[pts.length-1].date);
  let lo=Math.min(...pts.map(p=>p.v)),hi=Math.max(...pts.map(p=>p.v));
  if(lo===hi){lo-=1;hi+=1}
  const pad=(hi-lo)*.15;lo=Math.max(0,lo-pad);hi+=pad;
  const step=niceStep((hi-lo)/4);
  const y0=Math.floor(lo/step)*step,y1=Math.ceil(hi/step)*step;
  const X=p=>m.l+(t1===t0?iw/2:(t(p.date)-t0)/(t1-t0)*iw);
  const Y=v=>m.t+ih-(v-y0)/(y1-y0)*ih;
  let g='';
  for(let v=y0;v<=y1+1e-9;v+=step)g+=`<line x1="${m.l}" x2="${W-m.r}" y1="${Y(v)}" y2="${Y(v)}" stroke="var(--grid)"/><text x="${m.l-6}" y="${Y(v)+4}" text-anchor="end">${num(v)}</text>`;
  const nx=Math.min(pts.length,Math.max(2,Math.floor(iw/80)));
  const ticks=pts.length===1?[pts[0]]:Array.from({length:nx},(_,i)=>({date:new Date(t0+(t1-t0)*i/(nx-1)).toISOString().slice(0,10)}));
  ticks.forEach((p,i)=>{const x=pts.length===1?X(p):m.l+i/(nx-1)*iw;g+=`<text x="${x}" y="${H-8}" text-anchor="${i===0&&nx>1?'start':i===nx-1&&nx>1?'end':'middle'}">${fmtDate(p.date)}</text>`});
  const path=pts.map((p,i)=>(i?'L':'M')+X(p).toFixed(1)+' '+Y(p.v).toFixed(1)).join('');
  const dots=pts.map(p=>`<circle cx="${X(p)}" cy="${Y(p.v)}" r="4" fill="var(--line)" stroke="var(--surface)" stroke-width="2"/>`).join('');
  wrap.innerHTML=`<svg width="${W}" height="${H}" role="img" aria-label="${esc(sel)} ${label} over time"><title>${esc(sel)}: ${label} over time (${db.unit})</title>${g}<path d="${path}" fill="none" stroke="var(--line)" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>${dots}<line id="xh" y1="${m.t}" y2="${m.t+ih}" stroke="var(--muted)" stroke-width="1" visibility="hidden"/><circle id="hd" r="6" fill="var(--line)" stroke="var(--surface)" stroke-width="2" visibility="hidden"/></svg><div class="tip hidden" id="tip"></div>`;
  const svg=wrap.querySelector('svg'),tip=$('#tip'),xh=$('#xh'),hd=$('#hd');
  const show=ev=>{
    const r=svg.getBoundingClientRect(),px=ev.clientX-r.left;
    let p=pts[0];for(const q of pts)if(Math.abs(X(q)-px)<Math.abs(X(p)-px))p=q;
    xh.setAttribute('x1',X(p));xh.setAttribute('x2',X(p));xh.setAttribute('visibility','visible');
    hd.setAttribute('cx',X(p));hd.setAttribute('cy',Y(p.v));hd.setAttribute('visibility','visible');
    tip.innerHTML=`<b>${num(p.v)} ${db.unit}</b>${fmtDate(p.date,{day:'numeric',month:'short',year:'numeric'})}<br>${setsText(p.e)}`;
    tip.classList.remove('hidden');
    const tw=tip.offsetWidth/2;
    tip.style.left=Math.min(Math.max(X(p),tw),W-tw)+'px';tip.style.top=Math.max(Y(p.v)-12,tip.offsetHeight)+'px';
  };
  const hide=()=>{tip.classList.add('hidden');xh.setAttribute('visibility','hidden');hd.setAttribute('visibility','hidden')};
  svg.addEventListener('pointermove',show);svg.addEventListener('pointerdown',show);svg.addEventListener('pointerleave',hide);
}
function niceStep(raw){const p=10**Math.floor(Math.log10(raw)),f=raw/p;return(f<=1?1:f<=2?2:f<=5?5:10)*p}

/* ---------- settings ---------- */
$('#unit').onchange=e=>{db.unit=e.target.value;save();renderAll();resetForm(true)};
$('#export').onclick=()=>{
  const a=document.createElement('a');
  a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));
  a.download=`gym-log-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);
};
$('#import').onclick=()=>$('#file').click();
$('#file').onchange=async e=>{
  const f=e.target.files[0];if(!f)return;
  try{
    const d=JSON.parse(await f.text());
    if(!Array.isArray(d.entries))throw 0;
    const ok=d.entries.filter(x=>x&&x.date&&x.exercise&&Array.isArray(x.sets)&&x.sets.every(s=>isFinite(s.weight)&&isFinite(s.reps)));
    if(!confirm(`Replace current data with ${ok.length} entries from this file?`))return;
    db={entries:ok.map(x=>({id:x.id||Math.random().toString(36).slice(2),date:String(x.date),exercise:String(x.exercise),sets:x.sets.map(s=>({weight:+s.weight,reps:+s.reps}))})),unit:d.unit==='lb'?'lb':'kg'};
    save();renderAll();
  }catch{alert('That file is not a valid Gym Log backup.')}
  e.target.value='';
};

function renderAll(){
  $('#exlist').innerHTML=names().map(n=>`<option value="${esc(n)}">`).join('');
  $('#unit').value=db.unit;
  renderToday();
  if(!$('#progress').classList.contains('hidden'))renderProgress();
}
$('#date').value=today();
resetForm();renderAll();
let rt;addEventListener('resize',()=>{clearTimeout(rt);rt=setTimeout(()=>{if(!$('#progress').classList.contains('hidden'))renderProgress()},150)});
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('sw.js').catch(()=>{});
</script>
</body>
</html>
